#!/usr/bin/env python3
"""Parse norm sweep registry data into a clean table."""
import json
import re
from collections import defaultdict


def normalize_sr(metrics):
    """Extract SR as a fraction in [0, 1]."""
    # Prefer the canonical key, but tolerate alternatives.
    for key in ("overall_success_rate", "success_rate", "overall_sr", "sr"):
        if key in metrics and metrics[key] is not None:
            v = metrics[key]
            if isinstance(v, (int, float)):
                # Some entries are 0..100, others 0..1. Detect by magnitude.
                if v > 1.0:
                    return v / 100.0
                return float(v)
    return None


def parse_exp_id(exp_id):
    """Return (mode, epsilon, seed) or None if not parseable."""
    # Tolerate r2/r3/bjb1/bjb2 suffixes.
    pat = re.compile(
        r"^eval-(?:obs-only|perdof|mag-obsonly|mag-perdof)-(?:object-)?(norm003|norm005|norm01|norm02|norm03)-(?:object-)?(?:seed(\d+))?"
    )
    m = pat.match(exp_id)
    if not m:
        return None
    norm_token, seed = m.group(1), m.group(2)
    norm_map = {
        "norm003": 0.03,
        "norm005": 0.05,
        "norm01": 0.1,
        "norm02": 0.2,
        "norm03": 0.3,
    }
    eps = norm_map[norm_token]
    if "obs-only" in exp_id or "obsonly" in exp_id:
        mode = "obs_only"
    elif "perdof" in exp_id:
        mode = "perdof"
    else:
        return None
    return mode, eps, seed


def main():
    rows = []
    with open("/tmp/norm_sweep_raw.tsv") as f:
        for line in f:
            line = line.rstrip("\n")
            if not line:
                continue
            parts = line.split("\t")
            exp_id, conclusion, metrics_json = parts[0], parts[1], parts[2]
            if "k5-" in exp_id:
                continue  # K=5 variants are a different sweep
            parsed = parse_exp_id(exp_id)
            if parsed is None:
                continue
            mode, eps, seed = parsed
            try:
                metrics = json.loads(metrics_json) if metrics_json else {}
            except json.JSONDecodeError:
                metrics = {}
            sr = normalize_sr(metrics)
            if sr is None:
                continue
            rows.append({
                "exp_id": exp_id,
                "mode": mode,
                "epsilon": eps,
                "seed": seed,
                "sr": sr,
            })

    # Exclude per D084: seed42 norm02 obs_only (SR=20% anomaly)
    rows = [r for r in rows if not (
        r["mode"] == "obs_only" and r["epsilon"] == 0.2 and r["seed"] == "42"
    )]

    # Group and summarize
    groups = defaultdict(list)
    for r in rows:
        groups[(r["mode"], r["epsilon"])].append(r["sr"])

    print(f"{'mode':<10} {'eps':<6} {'n':<4} {'mean':<7} {'std':<7} {'min':<6} {'max':<6}")
    summary = {}
    for (mode, eps), srs in sorted(groups.items()):
        import statistics
        n = len(srs)
        mean = statistics.mean(srs)
        std = statistics.stdev(srs) if n > 1 else 0.0
        print(f"{mode:<10} {eps:<6} {n:<4} {mean:<7.4f} {std:<7.4f} {min(srs):<6.3f} {max(srs):<6.3f}")
        summary[f"{mode}_{eps}"] = {
            "mode": mode, "epsilon": eps, "n": n,
            "mean": mean, "std": std, "min": min(srs), "max": max(srs),
            "values": srs,
        }

    print("\nALL ROWS:")
    for r in sorted(rows, key=lambda x: (x["mode"], x["epsilon"], x["seed"] or "")):
        print(f"  {r['mode']:<10} eps={r['epsilon']:<5} seed={r['seed']:<5} sr={r['sr']:.3f}  ({r['exp_id']})")

    with open("/tmp/norm_sweep_clean.json", "w") as f:
        json.dump({"rows": rows, "summary": summary}, f, indent=2)


if __name__ == "__main__":
    main()

